if transparent then
  for _, name in ipairs({ "Normal", "SignColumn", "FoldColumn" }) do
    core[key][name].bg = nil
  end
else
  for _, name in ipairs({ "NormalNC", "WinBar", "WinBarNC" }) do
    groups[name].bg = p.bg
  end
end
for name, spec in pairs(core[key]) do
  vim.api.nvim_set_hl(0, name, spec)
end
for name, spec in pairs(groups) do
  vim.api.nvim_set_hl(0, name, spec)
end

-- ANSI colours for :terminal; the hero is magenta, bright variants reuse the base colours
local term = ansi[key]
for i, c in ipairs(term) do
  vim.g["terminal_color_" .. (i - 1)] = c
end

-- Re-apply when 'background' changes, so :set bg=light just works
local group = vim.api.nvim_create_augroup("MiamiCruise", { clear = true })
vim.api.nvim_create_autocmd("OptionSet", {
  group = group,
  pattern = "background",
  callback = function()
    if vim.g.colors_name == "miami-cruise" then
      vim.schedule(function()
        vim.cmd.colorscheme("miami-cruise")
      end)
    end
  end,
})
